 let inspectionSelectedId=null,inspectionStartNew=false;
 const inspectionPhotos=new Map(),inspectionTypes={delivery:'Entrega',periodic:'Periódica',return:'Devolução'},inspectionStatuses={draft:'Rascunho',submitted:'Aguardando conferência',changes_requested:'Correção solicitada',approved:'Aprovada no exemplo'};
 function driverInspection(){const d=driverProfile(),records=I.forDriver(ops,d.id),selected=inspectionStartNew?null:(records.find(r=>r.id===inspectionSelectedId)||records.find(r=>['draft','changes_requested'].includes(r.status)));if(selected)inspectionSelectedId=selected.id;const vehicleId=driverVehicle()?.id;return `<div class="notice">Vistorie o veículo, informe avarias e envie para conferência. A entrega só é liberada após revisão da gestão.</div>${selected?inspectionEditor(selected):`<form id="inspection-create-form" class="gap">${select('type','Tipo da vistoria','periodic',Object.entries(inspectionTypes))}${vehicleId?row('Veículo previsto no vínculo',esc(vehicleId)):'<p class="notice amber">A gestão ainda precisa indicar o veículo no cadastro ou no contrato.</p>'}<div class="form-actions"><button type="submit" class="btn primary" ${vehicleId?'':'disabled'}>Iniciar vistoria</button></div><p class="caption">Veículo selecionado aqui apenas prepara a vistoria; a gestão ainda precisa conferir disponibilidade e entrega.</p></form>`}<div class="gap">${panel('Minhas vistorias',records.length?records.map(r=>row(r.id+' · '+inspectionTypes[r.type],tag(inspectionStatuses[r.status],r.status==='approved'?'green':'amber'),r.vehicleId+' · '+num(r.km)+' km')+(r.review?`<p class="notice gap">Parecer: ${esc(r.review.note)}</p>`:'')+btn(['draft','changes_requested'].includes(r.status)?'Continuar vistoria':'Ver vistoria enviada','inspection-select','',`data-id="${r.id}"`)).join(''):'<p class="caption">Nenhuma vistoria iniciada neste perfil.</p>',selected?btn('Nova vistoria','inspection-new'):'')}</div>`;}
 function inspectionImage(record,slot){const e=record.evidence.find(e=>e.slot===slot),url=inspectionPhotos.get(record.id+':'+slot);if(url)return `<img src="${url}" alt="Foto temporária da ${esc(I.slots.find(([k])=>k===slot)[1])}"><small>Arquivo apenas nesta sessão</small>`;if(e?.source==='illustrative')return `<div class="evidence-sample"><svg viewBox="0 0 180 80" aria-hidden="true"><path d="M20 51L39 45L54 25H119L137 44L158 51V65H20Z" fill="#abc6b5" stroke="#477861" stroke-width="2"/><path d="M60 30H112L124 44H49Z" fill="#e8f1ed"/><circle cx="49" cy="64" r="12" fill="#4a5e50"/><circle cx="130" cy="64" r="12" fill="#4a5e50"/></svg><small>EVIDÊNCIA ILUSTRATIVA</small></div>`;return `<div class="evidence-empty">${e?'Arquivo expirado ao recarregar':'Sem imagem nesta vista'}<small>${e?'Selecione novamente nesta sessão':'Anexe uma foto ou use o exemplo'}</small></div>`;}
 function inspectionEditor(r){if(!['draft','changes_requested'].includes(r.status))return inspectionRead(r,false)+btn('Iniciar outra vistoria','inspection-new');return `<form id="inspection-work-form" class="gap" data-inspection-id="${r.id}"><div class="fields">${input('km','Hodômetro · km',r.km,'type="number" min="0" step="1" required')}${input('fuel','Combustível · %',r.fuel,'type="number" min="0" max="100" step="1" required')}</div>${section('1. Confira os itens','Marque OK, avaria ou não aplicável em cada item.')}<div class="inspection-items">${I.items.map(([key,label])=>select('check-'+key,label,r.items[key],[['','Selecionar'],['ok','OK · conferido'],['damage','Avaria / atenção'],['na','Não aplicável']])).join('')}</div><label class="field gap">Avarias e observações<textarea name="note" rows="3" maxlength="1500" placeholder="Descreva o ponto, lado do carro e o que precisa ser conferido.">${esc(r.note)}</textarea></label>${section('2. Registre as vistas','Fotos locais servem só para visualizar esta sessão; não são enviadas nem salvas no navegador.')}<div class="evidence-grid">${I.slots.map(([key,label])=>`<label class="evidence-slot"><strong>${label}</strong>${inspectionImage(r,key)}<input type="file" accept="image/*" capture="environment" data-inspection-photo="${key}" data-inspection-id="${r.id}" aria-label="Foto: ${label}"></label>`).join('')}</div><div class="actions gap">${btn('Preencher imagens de exemplo','inspection-examples','',`data-id="${r.id}"`)}</div><div class="notice gap">Nenhuma foto ou assinatura real é armazenada neste protótipo. As imagens de exemplo são ilustrações. O sistema operacional terá upload privado e histórico por vistoria.</div>${r.review?`<div class="notice amber gap"><strong>Correção solicitada:</strong> ${esc(r.review.note)}</div>`:''}<div class="form-actions"><button type="submit" class="btn">Salvar rascunho</button>${btn('Enviar para conferência','inspection-send','primary',`data-id="${r.id}"`)}</div></form>`;}
 function inspectionRead(r,admin=true){return row('Vistoria',r.id+' · '+inspectionTypes[r.type])+row('Motorista e veículo',esc(M.driver(ops,r.driverId).name)+' · '+r.vehicleId)+row('Situação',tag(inspectionStatuses[r.status],r.status==='approved'?'green':'amber'))+row('Hodômetro / combustível',num(r.km)+' km · '+num(r.fuel)+'%')+table(['Item','Registro'],I.items.map(([key,label])=>`<tr><td>${label}</td><td>${tag({ok:'OK',damage:'Avaria / atenção',na:'Não aplicável'}[r.items[key]]||'Pendente',r.items[key]==='damage'?'amber':'')}</td></tr>`).join(''))+`<p class="caption gap">Observações: ${esc(r.note||'Nenhuma observação registrada.')}</p><div class="evidence-grid gap">${I.slots.map(([key,label])=>`<div class="evidence-slot"><strong>${label}</strong>${inspectionImage(r,key)}</div>`).join('')}</div><p class="caption">Evidências ilustrativas/temporárias, sem validade de arquivo assinado. ${r.submittedAt?'Envio registrado em '+esc(new Date(r.submittedAt).toLocaleString('pt-BR'))+'.':''}</p>`+(r.review?`<div class="notice gap">Conferência: ${esc(r.review.note)}</div>`:'')+(admin&&r.status==='submitted'?`<form id="inspection-review-form" class="gap"><input type="hidden" name="entityId" value="${r.id}">${select('action','Decisão da conferência','changes',[['changes','Devolver para correção'],['approve','Aprovar vistoria no exemplo']])}<label class="field gap">Parecer e orientação<textarea name="note" required rows="3" maxlength="1000"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Registrar conferência</button></div><p class="caption">Itens de segurança com avaria impedem a aprovação. Conferir vistoria não assina contrato nem inicia aluguel.</p></form>`:'');}
 function inspectionAdmin(){const records=I.ensure(ops).records;return `<div class="notice">Checklists enviados pelo app do motorista. Revise itens, avarias e evidências antes de liberar a entrega.</div>${records.length?records.slice().reverse().map(r=>row(r.id+' · '+inspectionTypes[r.type],tag(inspectionStatuses[r.status],r.status==='approved'?'green':'amber'),esc(M.driver(ops,r.driverId).name)+' · '+r.vehicleId)+btn('Abrir conferência','inspection-review','',`data-id="${r.id}"`)).join(''):'<p class="caption gap">Ainda sem vistoria nesta versão. Abra App do motorista → Vistoria para iniciar.</p>'}`;}
 function inspectionSaveForm(){const form=root.querySelector('#inspection-work-form');if(!form)return null;const f=new FormData(form),r=I.lookup(ops,form.dataset.inspectionId);return I.save(ops,r.id,{km:Number(f.get('km')),fuel:Number(f.get('fuel')),note:f.get('note'),items:Object.fromEntries(I.items.map(([key])=>[key,f.get('check-'+key)||''])),evidence:r.evidence});}
 function inspectionAction(action,e){if(!action.startsWith('inspection-'))return false;if(action==='inspection-admin'){open('Central de vistorias',inspectionAdmin());return true;}if(action==='inspection-review'){open('Conferência · '+e.dataset.id,inspectionRead(I.lookup(ops,e.dataset.id)));return true;}if(action==='inspection-select'){inspectionStartNew=false;const r=I.lookup(ops,e.dataset.id);if(r.driverId!==activeDriverId)throw new RangeError('Esta vistoria não pertence ao perfil selecionado.');inspectionSelectedId=r.id;inspectionStartNew=false;}else if(action==='inspection-new'){inspectionSelectedId=null;inspectionStartNew=true;}else if(action==='inspection-send'){const r=inspectionSaveForm();if(!r)throw new RangeError('Abra o rascunho antes de enviar.');if(r.evidence.some(ev=>ev.source==='temporary'&&!inspectionPhotos.has(r.id+':'+ev.slot)))throw new RangeError('As fotos temporárias expiraram. Selecione de novo ou use imagens de exemplo.');I.submit(ops,r.id);toast('Vistoria enviada para conferência. A entrega ainda depende da gestão.');}else if(action==='inspection-examples'){const r=inspectionSaveForm()||I.lookup(ops,e.dataset.id);r.evidence=I.slots.map(([slot])=>({slot,source:'illustrative'}));for(const [slot]of I.slots){const key=r.id+':'+slot,url=inspectionPhotos.get(key);if(url)URL.revokeObjectURL(url);inspectionPhotos.delete(key);}}else return false;render();persist();return true;}
 function inspectionSubmit(form,f){if(form.id==='inspection-work-form'){inspectionSaveForm();persist();toast('Rascunho da vistoria preservado; fotos ficam apenas nesta sessão.');return true;}if(form.id==='inspection-create-form'){const d=driverProfile(),vehicleId=driverVehicle()?.id;const r=I.create(ops,{driverId:d.id,vehicleId,type:String(f.get('type'))});inspectionSelectedId=r.id;inspectionStartNew=false;render();persist();return true;}if(form.id==='inspection-review-form'){I.review(ops,String(f.get('entityId')),{action:String(f.get('action')),note:String(f.get('note'))});close();render();persist();toast('Parecer registrado na vistoria.');return true;}return false;}
 function inspectionPhotoChange(input){if(!input.dataset.inspectionPhoto)return;const r=inspectionSaveForm()||I.lookup(ops,input.dataset.inspectionId),file=input.files?.[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>8*1024*1024)throw new RangeError('Escolha uma imagem de até 8 MB.');const slot=input.dataset.inspectionPhoto,key=r.id+':'+slot,previous=inspectionPhotos.get(key);if(previous)URL.revokeObjectURL(previous);inspectionPhotos.set(key,URL.createObjectURL(file));r.evidence=r.evidence.filter(e=>e.slot!==slot).concat({slot,source:'temporary'});persist();render();}
